#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, b, c, d;
    cin >> n >> b >> c >> d;

    vector<int> dp(n + 1, -1);
    dp[0] = 0;

    for (int i = 1; i <= n; ++i) {
        for (int length : {b, c, d}) {
            if (length > 0 && i >= length && dp[i - length] != -1) {
                dp[i] = max(dp[i], dp[i - length] + 1);
            }
        }
    }

    cout << dp[n] << '\n';
    return 0;
}

