#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, b, c, d;
    cin >> n >> b >> c >> d;

    long long ans = 0;

    for (long long i = 0; i <= 4001; ++i) {
        for (long long j = 0; j <= 4001; ++j) {
            long long need = i * b + j * c;
            if (need <= n && d != 0 && (n - need) % d == 0) {
                ans = max(ans, i + j + (n - need) / d);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

